CREATE TYPE "InvoiceStatus" AS ENUM ('DRAFT','ISSUED','PAID','CANCELLED');
CREATE TABLE "AppSetting" ("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL,"section" TEXT NOT NULL,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "AppSetting_section_key_key" ON "AppSetting"("section","key"); CREATE INDEX "AppSetting_section_idx" ON "AppSetting"("section");
CREATE TABLE "ExpenseCategory" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Expense" ("id" TEXT PRIMARY KEY,"categoryId" TEXT NOT NULL,"orderId" TEXT,"amountMinor" INTEGER NOT NULL,"currency" TEXT NOT NULL,"incurredAt" TIMESTAMP(3) NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3));
CREATE INDEX "Expense_incurredAt_archivedAt_idx" ON "Expense"("incurredAt","archivedAt"); CREATE INDEX "Expense_orderId_idx" ON "Expense"("orderId");
CREATE TABLE "Invoice" ("id" TEXT PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"orderId" TEXT NOT NULL,"status" "InvoiceStatus" NOT NULL DEFAULT 'DRAFT',"language" TEXT NOT NULL DEFAULT 'ru',"currency" TEXT NOT NULL,"issueDate" TIMESTAMP(3) NOT NULL,"dueDate" TIMESTAMP(3),"seller" JSONB NOT NULL,"customer" JSONB NOT NULL,"items" JSONB NOT NULL,"notes" TEXT,"totalMinor" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3));
CREATE INDEX "Invoice_orderId_createdAt_idx" ON "Invoice"("orderId","createdAt"); CREATE INDEX "Invoice_issueDate_status_idx" ON "Invoice"("issueDate","status");
ALTER TABLE "Expense" ADD CONSTRAINT "Expense_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "ExpenseCategory"("id"); ALTER TABLE "Expense" ADD CONSTRAINT "Expense_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE SET NULL; ALTER TABLE "Invoice" ADD CONSTRAINT "Invoice_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id");
